  mspecP (OWN (p :: X) G) (raw_free p) (fun _ => OWN X G).
Proof.
ltac2:(KReplay.run1 (kr_t_KEvP ()) [] "h01Gh12HGh21Xh31pp;1p;3p;2p;4p;6g00C3j16Tg01ncj15Tg00X\j31Tg02K5j20Tg02`>j14Tg02a;j42Tg00n]j63Tg00mdR0#6g00KKR1g00Mop-0[[f1R2#5P1g00hCR1f3R39102f2R4'0%42f4/03V1P3P4P2f0C2E3W1X30W0W2o"). Qed.

